1: // DOCUMENTS: N simulated users — each tick, each user emits at most one
2: // request with probability `arrivalProb`, drawn from the engine's seeded
3: // RNG (passed in; this module holds no randomness of its own, so count
4: // changes stay inside the deterministic action sequence). Each acting user
5: // owns its own Browser and cycles the slim paths a user might visit.
6: import { createBrowser } from './browser.js';
7: 
8: const PATHS = ['/', '/about', '/missing'];
9: 
10: export function createUsers({ count = 5, serverAddress = '10.1' } = {}) {
11:   let n = count;
12:   if (!Number.isInteger(n) || n < 0) {
13:     throw new Error(`users: count must be a non-negative integer, got ${n}`);
14:   }
15:   const browsers = []; // user i uses Browser-(i + 1) at mini-IP 10.(i + 2)
16: 
17:   function browserFor(i) {
18:     if (!browsers[i]) {
19:       browsers[i] = createBrowser({ name: `Browser-${i + 1}`, address: `10.${i + 2}` });
20:     }
21:     return browsers[i];
22:   }
23: 
24:   return {
25:     setCount(next) {
26:       if (!Number.isInteger(next) || next < 0) {
27:         throw new Error(`users: count must be a non-negative integer, got ${next}`);
28:       }
29:       n = next;
30:     },
31:     getCount() {
32:       return n;
33:     },
34:     step(rng, arrivalProb) {
35:       const requests = [];
36:       for (let i = 0; i < n; i++) {
37:         if (rng() < arrivalProb) {
38:           const browser = browserFor(i);
39:           const request = browser.createRequest(PATHS[i % PATHS.length]);
40:           requests.push({ userId: i, from: browser.address, to: serverAddress, request });
41:         }
42:       }
43:       return requests;
44:     },
45: 
46:     // DOCUMENTS: a served exchange is routed back to the browser whose
47:     // mini-IP host number it carries (from "10.<i + 2>" -> browser i) so
48:     // every browser keeps its own rendered last() state.
49:     receiveResponse(exchange) {
50:       const i = Number(String(exchange.from).split('.')[1]) - 2;
51:       if (i >= 0) browserFor(i).receiveResponse(exchange);
52:     },
53: 
54:     // One entry per simulated browser (10.2 .. 10.(n + 1)) with its current
55:     // rendered viewport state — after `Math.random()`-free construction, so
56:     // calling it does not disturb the engine's RNG sequence.
57:     getBrowsers() {
58:       return Array.from({ length: n }, (_, i) => {
59:         const b = browserFor(i);
60:         return { index: i, name: b.name, address: b.address, lastDisplay: b.last() };
61:       });
62:     },
63:   };
