hostedStage6Sentences:

```js
function hostedStage6Sentences(t, snapshot, from, serverAddress, target) {
  const total = t.totalHops ?? 10;
  const dnsAddr = snapshot.dns?.address ?? '10.60';
  const emit = `Hop 1/${total}: Browser (${from}) emits "${t.request}"`;
  const ask = `Hop 2/${total}: Browser (${from}) asks DNS (${dnsAddr}) for ${t.dnsHost}`;
  if (t.dnsStatus === 'NX') {
    return [
      emit,
      ask,
      `Hop 3/${total}: DNS (${dnsAddr}) -> Browser (${from}): NX no record — no GET emitted`,
    ];
  }
  const answer = `Hop 3/${total}: DNS (${dnsAddr}) -> ${from}: "${t.dnsHost} = ${t.dnsTarget}" (dns ${t.dnsStatus})`;
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  if (t.asyncJob) {
    return [
      emit, ask, answer,
      `Hop 4/${total}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `Hop 5/${total}: LoadBalancer (${serverAddress}) -> ${target} queue`,
      `Hop 6/${total}: WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `Hop 7/${total}: WebServer (${target}) -> "202 Accepted"`,
      `Hop 8/${total}: Network delivers 202 response to ${from}`,
      `Hop 9/${total}: Browser (${from}) received and displayed 202 Accepted`,
      `Hop 10/${total}: Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  const dbOp = dbOpStory(t, snapshot);
  return [
    emit, ask, answer,
    `Hop 4/${total}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `Hop 5/${total}: LoadBalancer (${serverAddress}) -> ${target} queue`,
    `Hop 6/${total}: ${dbOp}`,
    `Hop 7/${total}: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `Hop 8/${total}: Network delivers ${t.status} response to ${from}`,
    `Hop 9/${total}: Browser (${from}) received and displayed ${t.status}`,
    `Hop 10/${total}: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}
```

