//
// CHECKS: the constructor rejects a non mini-IP interface, a non-positive
// ttl... (no ttl here) — rejects non mini-IP addresses and both interfaces
// living in the same network (a router joins two subnets, not one).
const MINI_IP = /^\d+\.\d+$/;
const netOf = (addr) => String(addr).split('.')[0];

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  if (!MINI_IP.test(rightAddress)) throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  if (netOf(leftAddress) === netOf(rightAddress)) {
    throw new Error(`router: both interfaces live in network ${netOf(leftAddress)} — a router joins two subnets`);
  }
  let left = null;
  let right = null;
  let routed = 0;

  function networkFor(address) {
    const net = netOf(address) === netOf(rightAddress) ? right : netOf(address) === netOf(leftAddress) ? left : null;
    if (!net) throw new Error(`router: no route to ${address} (joins ${leftAddress} ⇄ ${rightAddress})`);
    return net;
  }

  return {
    get leftAddress() { return leftAddress; },
    get rightAddress() { return rightAddress; },

    attach(leftNetwork, rightNetwork) {
      left = leftNetwork;
      right = rightNetwork;
    },

    // The router's 20.x interface: in 6a the only resident of subnet 20, so
    // a direct frame to rightAddress lands here and earns the gateway
    // receipt (Stage 6b replaces this with the CDN edge server).
    handleRequest() {
      return `200 gateway ${rightAddress} (no 20.x hosts yet — Stage 6b adds the CDN edge)`;
    },

    forward({ from, to, request }) {
      routed += 1;
      return networkFor(to).send({ from, to, request });
    },

    forwardToQueue(message) {
      routed += 1;
      return networkFor(message.to).deliverToQueue(message);
    },

    snapshot() {
      return { leftAddress, rightAddress, routed };
    },
  };
}
