// DOCUMENTS: the Stage 6 component — a DNS resolver with a tick-TTL ledger.
// It mirrors the Cache's tick-based TTL pattern (js/sim/cache.js): the
// authoritative table (name -> mini-IP) warms a ledger entry on a miss, a
// lookup inside ttlTicks is answered from the ledger (a real Map lookup on
// the request path, not a probability), and an entry whose expiry tick has
// arrived is consulted from the authoritative table again. Deterministic by
// construction: no clock, no RNG — time arrives as the `currentTick`
// argument, the same way the Cache and the WebServer keep time.
//
// Unknown names answer NX at the DNS layer: the resolver reports the miss,
// the browser renders the NX card, and no GET is emitted (the fail-loud
// throw rule belongs to cross-subnet addresses, not to names).
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration).
const MINI_IP = /^\d+\.\d+$/;

export function createDns({
  address = '10.60',
  ttlTicks = 300,
  records = { 'example.com': '10.1' },
} = {}) {
  if (!MINI_IP.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const ledger = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry:
  // resolved at tick T with ttlTicks = 300 means alive through tick T + 299.
  function evictExpired(currentTick = 0) {
    for (const [name, entry] of ledger) {
      if (currentTick >= entry.expiresAtTick) {
        ledger.delete(name);
      }
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = ledger.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'HIT', name, target: entry.target };
    }
    const target = records[name] ?? null;
    if (target) {
      authoritative += 1;
      ledger.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
      lastLookup = { name, status: 'MISS', target, atTick: currentTick };
      return { status: 'MISS', name, target };
    }
    lastLookup = { name, status: 'NX', atTick: currentTick };
    return { status: 'NX', name };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      lastLookup,
      cache: [...ledger.values()].map((e) => ({
        name: e.name,
        target: e.target,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    get ttlTicks() {
      return ttlTicks;
    },
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 cross-subnet Router — one gateway object joining
// two createNetwork() instances (the 10.x wire and the 20.x wire). A frame
// addressed to the other subnet takes exactly one router hop: the source
// network forwards it here, the hop counts in `routed`, and the frame is
// delivered into the destination network with every field (isYou included)
// riding through untouched. The router's own interfaces are the only
// residents of 6a's otherwise empty 20.x side — Stage 6b puts the CDN edge
// there, and this component keeps the fail-loud story in the meantime.
//
// CHECKS: the constructor rejects an interface that is not a two-number
// mini-IP and both interfaces living in the same network number (a router
// joins two subnets, not one).
const MINI_IP = /^\d+\.\d+$/;
const netOf = (addr) => String(addr).split('.')[0];

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  if (netOf(leftAddress) === netOf(rightAddress)) {
    throw new Error(
      `router: both interfaces live in network ${netOf(leftAddress)} — a router joins two subnets`,
    );
  }
  let left = null;
  let right = null;
  let routed = 0;

  function networkFor(address) {
    const net =
      netOf(address) === netOf(rightAddress)
        ? right
        : netOf(address) === netOf(leftAddress)
          ? left
          : null;
    if (!net) {
      throw new Error(`router: no route to ${address} (joins ${leftAddress} ⇄ ${rightAddress})`);
    }
    return net;
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    attach(leftNetwork, rightNetwork) {
      left = leftNetwork;
      right = rightNetwork;
    },

    // The router's 20.x interface answers as the subnet boundary: in 6a no
    // host lives behind it, so a direct frame to rightAddress earns the
    // gateway receipt instead of a served page (Stage 6b swaps this for the
    // CDN edge server).
    handleRequest() {
      return `200 gateway ${rightAddress} (no 20.x hosts yet — Stage 6b adds the CDN edge)`;
    },

    // CHECKS: the gateway interface has no request queue behind it in 6a —
    // a queue delivery into 20.x fails loud naming the missing edge instead
    // of crashing on a missing method.
    enqueue() {
      throw new Error(
        `router: no host behind ${rightAddress} accepts queue delivery (Stage 6b adds the CDN edge)`,
      );
    },

    // One hop per cross-subnet frame: counted before delivery so the trace
    // shows the router hop whatever the destination network answers.
    forward({ from, to, request }) {
      routed += 1;
      return networkFor(to).send({ from, to, request });
    },

    forwardToQueue(message) {
      routed += 1;
      return networkFor(message.to).deliverToQueue(message);
    },

    snapshot() {
      return { leftAddress, rightAddress, routed };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages within one subnet. Stage 6 adds
// an optional Router attachment: a frame addressed to another network
// number forwards through it into the joined network — exactly one router
// hop; unregistered same-subnet hosts still fail loud, and the pre-Stage-6
// single-wire network (no subnet, no router) keeps today's contract as-is.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered local hosts fail loud.
const MINI_IP = /^\d+\.\d+$/;
const netOf = (addr) => String(addr).split('.')[0];

export function createNetwork({ subnet = null } = {}) {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // A frame crosses subnets when the destination's network number differs
  // from this network's own. A subnet-less network (the Stage 1-5 wire)
  // forwards nothing and keeps the fail-loud contract unchanged.
  function crossesSubnet(to) {
    return router !== null && subnet !== null && netOf(to) !== subnet;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachRouter(attached) {
      router = attached;
    },

    send({ from, to, request }) {
      validate(from);
      validate(to);
      const server = servers.get(to);
      if (server) {
        return { from, to, request, response: server.handleRequest(request) };
      }
      if (crossesSubnet(to)) {
        return router.forward({ from, to, request });
      }
      throw new Error(`network: no server at ${to}`);
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    // Cross-subnet queue deliveries take the same one router hop.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      const server = servers.get(to);
      if (server) {
        server.enqueue({ id, from, to, request, atTick, isYou });
        return;
      }
      if (crossesSubnet(to)) {
        return router.forwardToQueue({ id, from, to, request, atTick, isYou });
      }
      throw new Error(`network: no server at ${to}`);
    },
  };
}

