// Stage 6: an NX answer keeps its status token verbatim ("NX no record")
// so the browser card renders the resolver's miss instead of a NaN badge.
parseResponse(raw) {
  const [statusToken, ...bodyParts] = String(raw).trim().split(' ');
  const status = statusToken === 'NX' ? 'NX' : Number(statusToken);
  return { status, body: bodyParts.join(' ') };
},

