// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
// (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
// backend's cache-aside lookup and the HTTP response emission split into
// two hops so the learner can watch Cache 10.20 answer, then the backend
// emit); 7 in Stage 4 (the Database hop inserted after the cache check —
// the WRITE to Primary 10.30, the fresh or stale SELECT from Replica
// 10.31, or the SKIP a warm cache HIT earns); 8 in Stage 5 (the async
// worker-queue round-trip).
//
// Stage 6 branches on the browser path's shape (DL-3/DL-4): a hosted path
// ("example.com/about") inserts the DNS round-trip — ask DNS 10.60, then
// the answer — before the Stage 5 chain replays two hops later (10 hops
// total); a host-less path ("/about") keeps the Stage 5 story byte-identical
// at 8 hops and never touches DNS. An unknown name answers NX on the
// answer hop: the record lands on the browser card and no GET is emitted.
//
// The machine owns the trace state and hop transitions; the engine owns
// the clock, the served-exchange record, and browser delivery, handed in
// as the callbacks below.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance.
export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
    throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  let trace = { hop: 0, totalHops: null };
  let served = null; // the drained response record, held between narrative hops

  // CHECKS: a hosted browser path carries a host before its first slash
  // ("example.com/about"); a plain path ("/about") is host-less and never
  // touches DNS — the named counter-example behind the Stage 6 trace branch.
  function hostedPathOf(path) {
    const text = String(path);
    const slash = text.indexOf('/');
    return slash > 0 ? { host: text.slice(0, slash), resolved: text.slice(slash) } : null;
  }

  function freshTrace({ method, path, from }) {
    const hosted = stage === 6 ? hostedPathOf(path) : null;
    return {
      hop: 1,
      method,
      path,
      from,
      request: `${method} ${path}`,
      host: hosted ? hosted.host : null,
      dnsStatus: null,
      dnsTarget: null,
      targetServer: stage === 1 ? serverAddress : null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      asyncJob: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
      totalHops: hosted ? 10 : stage === 6 ? 8 : stage === 5 ? 8 : stage === 4 ? 7 : stage === 3 ? 6 : stage === 2 ? 5 : 4,
      done: false,
    };
  }

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: trace.request,
      response: trace.response,
    });
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      // A continuing hosted run replays the Stage 5 chain two hops later:
      // its frames 4..10 are Stage 5's frames 2..8, so the shared branches
      // below key on the Stage-5-equivalent hop k.
      const hosted = stage === 6 && trace.hop >= 1 && trace.host !== null;
      const k = hosted ? trace.hop - 2 : trace.hop;
      const finalHops = trace.totalHops ?? 99;
      let frame = null;
      if (trace.hop === 0 || trace.hop >= finalHops || trace.done) {
        trace = freshTrace({ method, path, from });
        served = null;
        frame = `${from} -> ${serverAddress} | ${trace.request}`;
      } else if (hosted && trace.hop === 1) {
        // Hop 2/N: the browser asks DNS 10.60 for the host. The resolver's
        // own lookup runs here — ledger hit, authoritative consult, or NX —
        // so the counters and the trace narrative consume the same message.
        trace.hop = 2;
        if (!dns) throw new Error('trace: a hosted stage-6 path needs the DNS resolver');
        const answer = dns.lookup(trace.host, getTick());
        trace.dnsStatus = answer.status;
        trace.dnsTarget = answer.target ?? null;
        frame = `${trace.from} -> ${dns.address} | ${trace.host}?`;
      } else if (hosted && trace.hop === 2) {
        // Hop 3/N: the answer hop. NX ends the run here — the record lands
        // on the browser card and no GET is emitted for an unknown name.
        trace.hop = 3;
        if (trace.dnsStatus === 'NX') {
          trace.response = 'NX no record';
          trace.status = 'NX';
          trace.body = 'no record';
          trace.done = true;
          frame = `${dns.address} -> ${trace.from} | NX no record`;
          finish(dns.address);
        } else {
          trace.path = String(trace.path).slice(String(trace.path).indexOf('/'));
          trace.request = `${trace.method} ${trace.path}`;
          frame = `${dns.address} -> ${trace.from} | ${trace.host} = ${trace.dnsTarget}`;
        }
      } else if (k === 1) {
        trace.hop += 1;
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) to LoadBalancer`;
      } else if (k === 2) {
        trace.hop += 1;
        const atTick = bumpTick();
        const target = lb.enqueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.request,
          atTick,
          isYou: true,
        });
        trace.targetServer = target;
        frame = `LB ${serverAddress} -> ${target} (${trace.request}) queued`;
      } else if (stage === 2 && k === 3) {
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        const you = drainUntilYou(backend);
        if (you) {
          serve(you);
          frame = `${backend.address} -> ${trace.from} | ${you.response}`;
        }
      } else if (stage === 2 && k === 4) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (stage === 3 && k === 3) {
        // The target backend checks Cache and serves the queued request;
        // the response record is held one hop so the learner sees the cache
        // lookup before the response leaves the backend.
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
        }
      } else if (stage === 3 && k === 4) {
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
        }
      } else if (stage === 3 && k === 5) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (stage === 4 && k === 3) {
        // The target backend checks Cache and serves the queued request (a
        // POST write-through carries cacheStatus INVALIDATE); the response
        // record is held so the learner watches the cache lookup, then the
        // database hop.
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
        }
      } else if (stage === 4 && k === 4) {
        // The database hop — the WRITE to Primary 10.30 (replication queued
        // toward 10.31), the fresh or stale SELECT from Replica 10.31, or
        // the SKIP a warm cache HIT earns.
        trace.hop += 1;
        if (served) {
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if (stage === 4 && k === 5) {
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (stage === 4 && k === 6) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if ((stage === 5 || stage === 6) && k === 3) {
        // An async POST /jobs enqueues to WorkerQueue 10.40; other requests
        // narrate the cache/database hop they actually took (the Stage 4
        // story) — no phantom async jobs on GET traces (DL-4).
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          trace.asyncJob = Boolean(served.asyncJob);
          if (served.asyncJob) {
            frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.path})`;
          } else if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if ((stage === 5 || stage === 6) && k === 4) {
        // The webserver answers — an immediate 202 for async jobs, the
        // actually-served response for everything else.
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = served.asyncJob
            ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
            : `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if ((stage === 5 || stage === 6) && k === 5) {
        // WebServer returns its response via Network
        trace.hop += 1;
        frame = `Network delivered ${trace.status} response to ${trace.from}`;
      } else if ((stage === 5 || stage === 6) && k === 6) {
        // Browser receives and displays the response
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
        frame = `Browser ${trace.from} received and displayed ${trace.status}`;
      } else if ((stage === 5 || stage === 6) && k === 7) {
        // Async job tails with the worker's commit; a request that was
        // served synchronously finds the worker idle.
        trace.hop += 1;
        const dbTarget = database ? database.primaryAddress : '10.30';
        const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
        frame = trace.asyncJob
          ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
          : `Worker ${workerAddr} idle — no async jobs in this trace`;
      }
      return frame;
    },

    snapshot() {
      return { ...trace };
    },
  };
}

