// DOCUMENTS: Stage 5 worker-queue jobs render one row per pending job with
// its enqueue tick; the queue stats and worker HUD mirror the counters and
// the active job (DESIGN.md queue-jobs-list).
function renderJobsInto(container, jobs) {
  container.replaceChildren(
    ...jobs.map((job) => {
      const item = document.createElement('li');
      item.className = 'route-item';
      item.textContent = `#${job.jobId} · ${job.path} · queued @ tick ${job.queuedAtTick}`;
      return item;
    }),
  );
}

// DOCUMENTS: DNS resolver ledger rows (Stage 6) render one row per live
// ledger entry with its resolved target and remaining TTL in ticks — the
// Map on screen, mirroring the cache-aside rows (DESIGN.md dns-entries-list).
function renderDnsEntries(entries) {
  els.dnsEntries.replaceChildren(
    ...entries.map((e) => {
      const item = document.createElement('li');
      item.className = 'route-item';
      item.textContent = `${e.name} -> ${e.target} · ttl ${e.ttlRemaining}t`;
      return item;
    }),
  );
}

